effect.shader:
void main() {
    if (abs(angle) < 0.01) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(samples), 4, 48);
    float rad = radians(angle);

    vec2 p = acScreenNorm - center;
    p.x *= acAspect;

    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = (float(i) / float(n) - 0.5) * rad;
        float c = cos(t), s = sin(t);
        vec2 q = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
        q.x /= acAspect;
        soma += texture(inputImg, q + center);
    }
    fragColor = soma / float(n + 1);
}
